import{_ as i,C as o,o as t,c as n,a2 as s,b as l,w as a,a as c,E as u,a3 as d}from"./chunks/framework.CZqXuAiL.js";const D=JSON.parse('{"title":"RouteX","description":"","frontmatter":{},"headers":[],"relativePath":"routex/index.md","filePath":"routex/index.md","lastUpdated":1782667567000}'),h={name:"routex/index.md"};function g(p,e,m,f,B,A){const r=o("Mermaid");return t(),n("div",null,[e[1]||(e[1]=s('<h1 id="routex" tabindex="-1">RouteX <a class="header-anchor" href="#routex" aria-label="Permalink to &quot;RouteX&quot;">​</a></h1><p>Fast reverse proxy for game server infrastructure with DDoS protection.</p><h2 id="what-is-routex" tabindex="-1">What is RouteX? <a class="header-anchor" href="#what-is-routex" aria-label="Permalink to &quot;What is RouteX?&quot;">​</a></h2><p>RouteX is a production-grade L3/L4/L7 reverse proxy built in Go. It proxies TCP and UDP traffic with iptables-backed rate limiting, a custom L7 application-layer protection engine, load balancing, health checking, bandwidth management, and a universal metrics API.</p><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>Multi-Layer DDoS Protection</strong>: L3/L4 iptables rules + L7 protocol inspection + behavioral scoring</li><li><strong>Game Protocol Detection</strong>: Built-in validators for Minecraft Java/Bedrock, FiveM, Garry&#39;s Mod</li><li><strong>Bandwidth Management</strong>: Per-proxy quotas (hourly/daily/weekly/monthly) with auto-suspension</li><li><strong>ACL System</strong>: Global + per-proxy IP whitelist/blacklist with live API management</li><li><strong>5 Load Balancing Algorithms</strong>: Round-robin, least-conn, ip-hash, weighted, random</li><li><strong>Universal Metrics</strong>: Prometheus, InfluxDB, CSV, JSON — all from one endpoint</li><li><strong>36 REST API Endpoints</strong>: Full programmatic control</li><li><strong>Zero-Downtime Reload</strong>: Per-proxy config hot-reload via file watcher</li></ul><h2 id="quick-links" tabindex="-1">Quick Links <a class="header-anchor" href="#quick-links" aria-label="Permalink to &quot;Quick Links&quot;">​</a></h2><ul><li><a href="/pingless-studios-docs/routex/getting-started/overview">Getting Started</a></li><li><a href="/pingless-studios-docs/routex/getting-started/installation">Installation</a></li><li><a href="/pingless-studios-docs/routex/reference/global-config">Configuration Reference</a></li><li><a href="/pingless-studios-docs/routex/api/endpoints">API Reference</a></li><li><a href="https://github.com/AnAverageBeing/RouteX-Reverse-Proxy" target="_blank" rel="noreferrer">GitHub Repository</a></li></ul><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2>',9)),(t(),l(d,null,{default:a(()=>[u(r,{id:"mermaid-90",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5BClients%5D%20--%3E%20B%5BRouteX%20Listeners%5D%0A%20%20%20%20B%20--%3E%20C%7BACL%20Check%7D%0A%20%20%20%20C%20--%3E%7CAllow%7C%20D%5BLoad%20Balancer%5D%0A%20%20%20%20C%20--%3E%7CDeny%7C%20X1%5BDrop%5D%0A%20%20%20%20D%20--%3E%20E%5BHealth%20Check%5D%0A%20%20%20%20E%20--%3E%20F%5BUpstream%20Servers%5D%0A%20%20%20%20B%20--%3E%20G%5Biptables%20Rate%20Limits%5D%0A%20%20%20%20B%20--%3E%20H%5BL7%20Engine%5D%0A%20%20%20%20H%20--%3E%20I%5BBehavioral%20Scoring%5D%0A%20%20%20%20I%20--%3E%20J%5BAuto-Ban%5D%0A%20%20%20%20B%20--%3E%20K%5BBandwidth%20Manager%5D%0A%20%20%20%20K%20--%3E%20L%5BQuota%20Enforcement%5D%0A%20%20%20%20L%20--%3E%20M%5BAuto-Suspend%5D%0A%20%20%20%20B%20--%3E%20N%5BREST%20API%20%2B%20Metrics%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1}))])}const b=i(h,[["render",g]]);export{D as __pageData,b as default};
